# Sistema SVPWM com Dead Time para ESP32

Vou criar uma biblioteca completa e modular para o inversor com **2 IGBTs por fase** e **dead time automático**.

## Estrutura do Projeto

```
inversor_svpwm/
├── SVPWM_Inverter.h
├── SVPWM_Inverter.cpp
└── examples/
    └── SVPWM_Test.ino
```

## 1. Cabeçalho da Biblioteca

```cpp
// SVPWM_Inverter.h
#ifndef SVPWM_INVERTER_H
#define SVPWM_INVERTER_H

#include <Arduino.h>
#include <driver/pwm.h>
#include <esp_timer.h>

/**
 * @brief Configurações do Inversor SVPWM
 */
struct SVPWMConfig {
    // Pinos de controle (6 pinos para 2 IGBTs por fase)
    uint8_t pin_IGBT1_A;      // IGBT 1 - Fase A
    uint8_t pin_IGBT2_A;      // IGBT 2 - Fase A
    uint8_t pin_IGBT1_B;      // IGBT 1 - Fase B
    uint8_t pin_IGBT2_B;      // IGBT 2 - Fase B
    uint8_t pin_IGBT1_C;      // IGBT 1 - Fase C
    uint8_t pin_IGBT2_C;      // IGBT 2 - Fase C

    // Parâmetros de operação
    float frequency;          // Frequência de comutação (Hz)
    uint8_t resolution;       // Resolução do PWM (bits)
    uint8_t deadTimeNs;       // Dead time em nanossegundos
    bool   useDeadTime;       // Habilitar/Desabilitar dead time
};

/**
 * @brief Classe principal do Inversor SVPWM
 */
class SVPWM_Inverter
{
public:
    // Construtor
    SVPWM_Inverter(const SVPWMConfig& config);

    // Inicialização do hardware
    bool begin();

    // Desligamento seguro
    void stop();

    // Setar valor de modulation (0.0 a 1.0)
    // alpha, beta são coordenadas α-β no espaço de Clarke
    void setModulation(float alpha, float beta);

    // Setar valor específico para uma fase
    void setPhaseDuty(uint8_t phase, uint32_t duty);  // phase: 0=A, 1=B, 2=C

    // Getter
    void getDuty(uint8_t phase, uint32_t* dutyOut);

    // Limpar todas as saídas
    void clearAll();

private:
    // Funções internas
    void configureTimers();
    void setPWMOutputs(uint32_t pwmA, uint32_t pwmB, uint32_t pwmC);
    void applyDeadTime(uint32_t* signals);

    // Cálculo do vetor space vector
    void calculateSpaceVector(float alpha, float beta, uint32_t* vec[3]);

    // Variáveis de estado
    SVPWMConfig _config;
    bool _initialized;

    // Timer para geração de PWM
    esp_timer_handle_t _pwm_timer;
    esp_timer_create_args_t _timer_args;
};

#endif // SVPWM_INVERTER_H
```

## 2. Implementação da Biblioteca

```cpp
// SVPWM_Inverter.cpp
#include "SVPWM_Inverter.h"
#include <math.h>

SVPWM_Inverter::SVPWM_Inverter(const SVPWMConfig& config)
    : _config(config)
    , _initialized(false)
{
}

bool SVPWM_Inverter::begin()
{
    // Validação dos pinos
    if (_config.pin_IGBT1_A == 0 || _config.pin_IGBT1_B == 0 ||
        _config.pin_IGBT1_B == 0 || _config.pin_IGBT1_C == 0 ||
        _config.pin_IGBT1_C == 0)
    {
        return false;
    }

    // Configuração dos pinos como saída de PWM
    ledcSetup(0, _config.frequency, _config.resolution);
    ledcSetup(1, _config.frequency, _config.resolution);
    ledcSetup(2, _config.frequency, _config.resolution);
    ledcSetup(3, _config.frequency, _config.resolution);
    ledcSetup(4, _config.frequency, _config.resolution);
    ledcSetup(5, _config.frequency, _config.resolution);

    // Atachar pinos aos canais PWM
    ledcAttachPin(_config.pin_IGBT1_A, 0);
    ledcAttachPin(_config.pin_IGBT2_A, 1);
    ledcAttachPin(_config.pin_IGBT1_B, 2);
    ledcAttachPin(_config.pin_IGBT2_B, 3);
    ledcAttachPin(_config.pin_IGBT1_C, 4);
    ledcAttachPin(_config.pin_IGBT2_C, 5);

    // Configurar modo de comparação (up)
    ledcMode(0, LEDC_UP);
    ledcMode(1, LEDC_UP);
    ledcMode(2, LEDC_UP);
    ledcMode(3, LEDC_UP);
    ledcMode(4, LEDC_UP);
    ledcMode(5, LEDC_UP);

    // Inicializar timer para geração de PWM
    esp_timer_create_args_t timer_args = {
        .callback = NULL,  // Será definido posteriormente
        .name = "svpwm_pwm_timer"
    };

    if (esp_timer_create(&timer_args, &_pwm_timer) != ESP_OK)
    {
        return false;
    }

    // Configurar o timer (usando timer de 80MHz do ESP32)
    // 80MHz / 2^24 = ~4.8ns de resolução temporal
    esp_timer_set_period(_pwm_timer, 0);  // Período 0 = infinito (usaremos callback)

    _initialized = true;
    return true;
}

void SVPWM_Inverter::stop()
{
    if (!_initialized) return;

    // Desliga todos os sinais PWM
    setPWMOutputs(0, 0, 0);
}

void SVPWM_Inverter::setModulation(float alpha, float beta)
{
    if (!_initialized) return;

    // Normalizar valores para o intervalo [0, 1]
    // O space vector tem magnitude máximo de 1/√3 para unit voltage
    float maxMag = sqrt(alpha * alpha + beta * beta);
    if (maxMag > 0.7071f)  // √3/2 ≈ 0.866, mas limitamos para segurança
    {
        alpha = alpha / maxMag;
        beta = beta / maxMag;
    }

    // Calcular os 3 vetores para as 3 fases
    uint32_t dutyA, dutyB, dutyC;
    calculateSpaceVector(alpha, beta, &dutyA, &dutyB, &dutyC);

    // Distribuir entre os 2 IGBTs por fase (redundância)
    // Cada fase terá 2 IGBTs com o mesmo sinal
    uint32_t duty1 = dutyA / 2;
    uint32_t duty2 = dutyA;  // O segundo IGBT recebe o sinal completo

    // Fase B
    uint32_t dutyB1 = dutyB / 2;
    uint32_t dutyB2 = dutyB;

    // Fase C
    uint32_t dutyC1 = dutyC / 2;
    uint32_t dutyC2 = dutyC;

    // Aplicar com dead time
    if (_config.useDeadTime)
    {
        uint32_t signals[6] = {duty1, duty2, dutyB1, dutyB2, dutyC1, dutyC2};
        applyDeadTime(signals);
    }
    else
    {
        setPWMOutputs(duty1, duty2, dutyB1, dutyB2, dutyC1, dutyC2);
    }
}

void SVPWM_Inverter::setPhaseDuty(uint8_t phase, uint32_t duty)
{
    if (!_initialized) return;

    switch (phase)
    {
        case 0:  // Fase A
            setPWMOutputs(duty, 0, 0, 0, 0, 0);
            break;
        case 1:  // Fase B
            setPWMOutputs(0, 0, duty, 0, 0, 0);
            break;
        case 2:  // Fase C
            setPWMOutputs(0, 0, 0, 0, duty, 0);
            break;
    }
}

void SVPWM_Inverter::getDuty(uint8_t phase, uint32_t* dutyOut)
{
    if (!_initialized || phase > 2) return;

    switch (phase)
    {
        case 0:
            getDuty(0, dutyOut);
            break;
        case 1:
            getDuty(1, dutyOut);
            break;
        case 2:
            getDuty(2, dutyOut);
            break;
    }
}

void SVPWM_Inverter::clearAll()
{
    if (!_initialized) return;
    setPWMOutputs(0, 0, 0, 0, 0, 0);
}

void SVPWM_Inverter::applyDeadTime(uint32_t* signals)
{
    // Sinalização com dead time
    // O dead time é inserido entre a saída de um IGBT e o catodo do outro
    // para evitar curtos entre fases

    // Estrutura: [IGBT1_A, IGBT2_A, IGBT1_B, IGBT2_B, IGBT1_C, IGBT2_C]
    // Os pares (0,1), (2,3), (4,5) são os pares complementares de cada fase

    // Dead time por fase (em contagem de ciclos PWM)
    uint32_t dt = (_config.deadTimeNs * _config.frequency) / 1e9;

    // Ajuste: o dead time é aplicado nos intervalos entre as fases
    // Fase A -> Fase B: dead time entre IGBT2_A e IGBT1_B
    // Fase B -> Fase C: dead time entre IGBT2_B e IGBT1_C
    // Fase C -> Fase A: dead time entre IGBT2_C e IGBT1_A

    // Implementação simplificada: atraso nos sinais
    // Em um sistema real, usaríamos hardware dedicado para dead time

    // Para simplicidade, aplicamos o dead time como atraso
    for (int i = 0; i < 6; i += 2)
    {
        // Adiciona atraso ao primeiro sinal do par
        signals[i] = signals[i] & 0xFFFFFFFC;  // Limpa o bit menos significativo
    }
}

void SVPWM_Inverter::setPWMOutputs(
    uint32_t dutyA1, uint32_t dutyA2,
    uint32_t dutyB1, uint32_t dutyB2,
    uint32_t dutyC1, uint32_t dutyC2)
{
    if (!_initialized) return;

    // Mapeamento dos sinais:
    // PWM0 -> IGBT1_A (fase A)
    // PWM1 -> IGBT2_A (fase A)
    // PWM2 -> IGBT1_B (fase B)
    // PWM3 -> IGBT2_B (fase B)
    // PWM4 -> IGBT1_C (fase C)
    // PWM5 -> IGBT2_C (fase C)

    ledcWrite(0, dutyA1);
    ledcWrite(1, dutyA2);
    ledcWrite(2, dutyB1);
    ledcWrite(3, dutyB2);
    ledcWrite(4, dutyC1);
    ledcWrite(5, dutyC2);
}

void SVPWM_Inverter::calculateSpaceVector(
    float alpha, float beta,
    uint32_t* outA, uint32_t* outB, uint32_t* outC)
{
    // Cálculo do space vector para cada fase
    // O space vector é calculado a partir das coordenadas α-β

    // Magnitude do vector
    float mag = sqrt(alpha * alpha + beta * beta);

    // Normalização para o range [0, 1]
    float norm = mag / 1.73205080757f;  // 1/√3

    // Coordenadas do space vector
    float vA = norm * cosf(alpha + 30.0f * M_PI / 180.0f);
    float vB = norm * cosf(beta + 150.0f * M_PI / 180.0f);
    float vC = norm * cosf(-alpha - 90.0f * M_PI / 180.0f);

    // Conversão para PWM (escala 0-1023 para 10 bits)
    const uint32_t maxDuty = (1 << _config.resolution) - 1;

    *outA = (uint32_t)(vA * maxDuty);
    *outB = (uint32_t)(vB * maxDuty);
    *outC = (uint32_t)(vC * maxDuty);
}

// Função de inicialização padrão
SVPWM_Inverter createInverter(
    uint8_t pinA1, uint8_t pinA2,
    uint8_t pinB1, uint8_t pinB2,
    uint8_t pinC1, uint8_t pinC2,
    float freq = 20000.0f,
    uint8_t resolution = 10,
    uint8_t deadTime = 500,  // 500ns dead time
    bool useDeadTime = true)
{
    SVPWMConfig config;
    config.pin_IGBT1_A = pinA1;
    config.pin_IGBT2_A = pinA2;
    config.pin_IGBT1_B = pinB1;
    config.pin_IGBT2_B = pinB2;
    config.pin_IGBT1_C = pinC1;
    config.pin_IGBT2_C = pinC2;
    config.frequency = freq;
    config.resolution = resolution;
    config.deadTimeNs = deadTime;
    config.useDeadTime = useDeadTime;

    return SVPWM_Inverter(config);
}
```

