    .pin_IGBT1_B = 27,
    .pin_IGBT2_B = 28,
    .pin_IGBT1_C = 29,
    .pin_IGBT2_C = 30,
    .frequency = 20000.0f,      // 20 kHz
    .resolution = 10,           // 10 bits (1024 níveis)
    .deadTimeNs = 800,          // 800ns de dead time
    .useDeadTime = true
};

SVPWM_Inverter inverter(createInverter(
    config.pin_IGBT1_A, config.pin_IGBT2_A,
    config.pin_IGBT1_B, config.pin_IGBT2_B,
    config.pin_IGBT1_C, config.pin_IGBT2_C,
    config.frequency, config.resolution, config.deadTimeNs, config.useDeadTime
));

// Variáveis para controle
float alpha = 0.0f;
float beta = 0.5f;

void setup()
{
    Serial.begin(115200);

    // Inicializa o inversor
    if (!inverter.begin()) {
        Serial.println("Falha ao inicializar o inversor!");
        while (1);
    }

    Serial.println("Inversor SVPWM inicializado com sucesso!");
    Serial.printf("Frequência: %.0f Hz, Resolução: %d bits\n", 
                  config.frequency, config.resolution);
    Serial.printf("Dead time: %d ns\n", config.deadTimeNs);
}

void loop()
{
    // Exemplo: Modulação senoidal triplamente pulsante
    // Gera uma onda senoidal para cada fase com deslocamento de 120°

    static unsigned long lastUpdate = 0;
    unsigned long now = millis();

    // Atualiza a modulação a cada 5ms
    if (now - lastUpdate >= 5) {
        lastUpdate = now;

        // Ângulo de fase (0 a 2π)
        float angle = (float)(sin(radians(0)) * 0.5f + 
                            sin(radians(120)) * 0.5f + 
                            sin(radians(240)) * 0.5f);

        // Converte para coordenadas α-β
        alpha = angle * M_PI / 180.0f;
        beta = angle * 2.0f * M_PI / 180.0f;

        // Aplica a modulação
        inverter.setModulation(alpha, beta);

        // Mostra os valores no serial
        Serial.printf("α: %.3f, β: %.3f\n", alpha, beta);
    }

    // Exemplo: Chaveamento rápido para teste
