## 1. Cabeçalho da Biblioteca

```cpp
// SVPWM_Inverter.h
#ifndef SVPWM_INVERTER_H
#define SVPWM_INVERTER_H

#include <Arduino.h>
#include <driver/pwm.h>
#include <esp_timer.h>

/**
 * @brief Configurações do Inversor SVPWM
 */
struct SVPWMConfig {
    // Pinos de controle (6 pinos para 2 IGBTs por fase)
    uint8_t pin_IGBT1_A;      // IGBT 1 - Fase A
    uint8_t pin_IGBT2_A;      // IGBT 2 - Fase A
    uint8_t pin_IGBT1_B;      // IGBT 1 - Fase B
    uint8_t pin_IGBT2_B;      // IGBT 2 - Fase B
    uint8_t pin_IGBT1_C;      // IGBT 1 - Fase C
    uint8_t pin_IGBT2_C;      // IGBT 2 - Fase C

    // Parâmetros de operação
    float frequency;          // Frequência de comutação (Hz)
    uint8_t resolution;       // Resolução do PWM (bits)
    uint8_t deadTimeNs;       // Dead time em nanossegundos
    bool   useDeadTime;       // Habilitar/Desabilitar dead time
};

/**
 * @brief Classe principal do Inversor SVPWM
 */
class SVPWM_Inverter
{
public:
    // Construtor
    SVPWM_Inverter(const SVPWMConfig& config);

    // Inicialização do hardware
    bool begin();

    // Desligamento seguro
    void stop();

    // Setar valor de modulation (0.0 a 1.0)
    // alpha, beta são coordenadas α-β no espaço de Clarke
    void setModulation(float alpha, float beta);

    // Setar valor específico para uma fase
    void setPhaseDuty(uint8_t phase, uint32_t duty);  // phase: 0=A, 1=B, 2=C

    // Getter
    void getDuty(uint8_t phase, uint32_t* dutyOut);

    // Limpar todas as saídas
    void clearAll();

private:
    // Funções internas
