    ledcSetup(0, _config.frequency, _config.resolution);
    ledcSetup(1, _config.frequency, _config.resolution);
    ledcSetup(2, _config.frequency, _config.resolution);
    ledcSetup(3, _config.frequency, _config.resolution);
    ledcSetup(4, _config.frequency, _config.resolution);
